// ────────────────────────────────────────────────
// ① 여기 4개 링크를 실제 URL로 바꿔주세요
// ────────────────────────────────────────────────
const LINK_MISSION_BOARD   = "https://docs.google.com/spreadsheets/d/YOUR_MISSION_BOARD_ID";
const LINK_KDT_DASHBOARD   = "https://docs.google.com/spreadsheets/d/YOUR_KDT_DASHBOARD_ID";
const LINK_ANNUAL_SCHEDULE = "https://docs.google.com/spreadsheets/d/YOUR_ANNUAL_SCHEDULE_ID";
const LINK_NOTION          = "https://www.notion.so/YOUR_NOTION_PAGE";

// ────────────────────────────────────────────────
// RSS 피드 & 필터 키워드 (수정 불필요)
// ────────────────────────────────────────────────
const FEEDS = [
  { name: "전자신문",     url: "https://www.etnews.com/rss/" },
  { name: "ZDNet Korea", url: "https://zdnet.co.kr/rss/rss.aspx" },
  { name: "블로터",       url: "https://www.bloter.net/feed" },
  { name: "IT조선",       url: "https://it.chosun.com/rss/data/it.xml" },
];
const KEYWORDS = [
  "KDT", "내일배움", "부트캠프", "디지털 교육", "AI 교육",
  "코딩 교육", "취업 연계", "훈련 기관", "HRD", "K-Digital",
  "기술 교육", "디지털 훈련", "직업훈련", "재직자 훈련",
];

// ────────────────────────────────────────────────
// RSS 수집
// ────────────────────────────────────────────────
const articles = [];
for (const feed of FEEDS) {
  try {
    const resp = await fetch(feed.url, {
      headers: { "User-Agent": "MorningBriefingBot/1.0" },
      signal: AbortSignal.timeout(8000),
    });
    const raw = await resp.text();
    const items = raw.match(/<item>([\s\S]*?)<\/item>/g) || [];
    for (const item of items) {
      const title = (
        item.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/) ||
        item.match(/<title>([^<]*)<\/title>/)
      )?.[1]?.trim() ?? "";
      const link = (
        item.match(/<link>([^<]+)<\/link>/) ||
        item.match(/<guid[^>]*>(https?:\/\/[^<]+)<\/guid>/)
      )?.[1]?.trim() ?? "";
      const desc = (
        item.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/) ||
        item.match(/<description>([^<]*)<\/description>/)
      )?.[1] ?? "";
      const combined = (title + " " + desc).toLowerCase();
      if (KEYWORDS.some(kw => combined.includes(kw.toLowerCase()))) {
        articles.push({ title, link, source: feed.name });
      }
    }
  } catch (_) {
    // 피드 실패 시 스킵
  }
}

// ────────────────────────────────────────────────
// 날짜 포맷
// ────────────────────────────────────────────────
const now  = new Date();
const days = ["일", "월", "화", "수", "목", "금", "토"];
const pad  = n => String(n).padStart(2, "0");
const dateStr = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())} (${days[now.getDay()]})`;

// ────────────────────────────────────────────────
// 뉴스 섹션 텍스트
// ────────────────────────────────────────────────
const top5 = articles.slice(0, 5);
const newsText = top5.length > 0
  ? top5.map(a => `• <${a.link}|${a.title}>  _${a.source}_`).join("\n")
  : "_오늘은 관련 뉴스를 찾지 못했어요. 업계 동향을 직접 공유해주세요!_";

const ideationText =
  `💡 *KDT 업계 현황 — ${dateStr} 기준*\n` +
  `${newsText}\n` +
  `_💬 위 내용 보고 자유롭게 아이디어 달아주세요!_`;

// ────────────────────────────────────────────────
// Slack 블록 구성
// ────────────────────────────────────────────────
const blocks = [
  {
    type: "header",
    text: { type: "plain_text", text: `🌅  모닝 브리핑  |  ${dateStr}` },
  },
  { type: "divider" },
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text:
        "📋 *오늘의 대시보드*\n" +
        `• <${LINK_MISSION_BOARD}|미션 현황판>\n` +
        `• <${LINK_KDT_DASHBOARD}|KDT 대시보드>\n` +
        `• <${LINK_ANNUAL_SCHEDULE}|연간 일정>\n` +
        `• <${LINK_NOTION}|회의록 · 노션>`,
    },
  },
  { type: "divider" },
  {
    type: "section",
    text: { type: "mrkdwn", text: ideationText },
  },
];

return [{ json: { text: `모닝 브리핑 | ${dateStr}`, blocks } }];
